[
  {
    "statement": "Nine of eighteen studies on providing supplementary food for birds indicated that the practice increased the abundance, breeding population size, density, and overwinter survival of farmland birds.",
    "citations": [
      "648"
    ]
  },
  {
    "statement": "Five studies revealed that providing supplementary food for birds had no discernible impact on the abundance of breeding farmland birds or their success in reproducing.",
    "citations": [
      "648"
    ]
  },
  {
    "statement": "One study discovered that in one year, nests that were given extra food had lower fledging rates.",
    "citations": [
      "648"
    ]
  },
  {
    "statement": "Twenty-one of thirty separate studies examining the practice of sowing wild bird seed or cover mixture revealed beneficial outcomes.",
    "citations": [
      "594"
    ]
  },
  {
    "statement": "Fields planted with a wild bird cover mix had a higher density, abundance, and variety of bird species than other agricultural habitats.",
    "citations": [
      "594"
    ]
  },
  {
    "statement": "Nine replicated studies from France and the UK reported mixed or negative effects of wild bird cover on birds compared to other farmland habitats.",
    "citations": [
      "594"
    ]
  }
]

[
  {
    "statement": "No evidence was found for the effects of managing land under power lines to benefit wildlife.",
    "citations": [
      "99"
    ]
  }
]

[
  {
    "statement": "A review found that predators increased in crops adjacent to beetle banks.",
    "citations": [
      "729"
    ]
  },
  {
    "statement": "One study found that the effects of beetle banks on predator populations varied with time.",
    "citations": [
      "729"
    ]
  },
  {
    "statement": "One study found that beetle banks had no effect on predator populations.",
    "citations": [
      "729"
    ]
  },
  {
    "statement": "Two studies found that predators made small or slow movements from beetle banks to crops.",
    "citations": [
      "729"
    ]
  },
  {
    "statement": "One study found greater beetle activity in fields with beetle banks.",
    "citations": [
      "729"
    ]
  },
  {
    "statement": "The greater beetle activity found in one study did not improve pest predation.",
    "citations": [
      "729"
    ]
  },
  {
    "statement": "Four studies and a review found more invertebrate predators on beetle banks than in surrounding crops.",
    "citations": [
      "729"
    ]
  },
  {
    "statement": "One study found that the effects of beetle banks on invertebrate predators varied with time.",
    "citations": [
      "729"
    ]
  },
  {
    "statement": "A replicated, randomised study and a review found the largest pest reductions in areas closest to a beetle bank or on the beetle bank itself.",
    "citations": [
      "729"
    ]
  },
  {
    "statement": "One review found fewer pests in fields with a beetle bank than in fields without a beetle bank.",
    "citations": [
      "729"
    ]
  },
  {
    "statement": "One replicated, randomised, controlled trial and a review showed that beetle banks could create economic savings if the banks prevented pests from reaching a spray threshold.",
    "citations": [
      "729"
    ]
  },
  {
    "statement": "One replicated, randomised, controlled trial and a review showed that beetle banks could create economic savings if the banks prevented pests from causing 5% yield loss.",
    "citations": [
      "729"
    ]
  },
  {
    "statement": "Soybean was one of the crops studied in relation to beetle banks.",
    "citations": [
      "729"
    ]
  }
]

[
  {
    "statement": "A UK study found marking deer fences with orange netting resulted in fewer bird collisions.",
    "citations": [
      "238"
    ]
  },
  {
    "statement": "No evidence of the effects on farmland wildlife from marking fencing in general to avoid bird mortality has been captured.",
    "citations": [
      "706"
    ]
  },
  {
    "statement": "There is no evidence of the effects of avoiding lead shot on farmland wildlife.",
    "citations": [
      "100"
    ]
  }
]
